//! Differential checks against the Python engine: validators, reply parser, URL normalization and the
//! local-network rule on fixed and random inputs (fixture generated by `tools/gen_llm_parity.py`).

use serial_test::serial;

use se_core::Value;
use se_translate::external::{api_key_transport_allowed, is_local_network_host, normalize_external_chat_url};
use se_translate::prompts::parse_numbered_translations;
use se_translate::validate::{clean_translation_pair, has_source_translation_pair, has_unrequested_markup, looks_untranslated};

fn fixture() -> Value {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/llm_parity.json")).unwrap();
    se_core::json::parse(&text).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v.get(k).and_then(Value::as_str).unwrap()
}

fn opt<'a>(v: &'a Value, k: &str) -> Option<&'a str> {
    v.get(k).and_then(Value::as_str)
}

#[test]
fn test_validators_match_python() {
    let f = fixture();
    let cases = f.get("validators").and_then(Value::as_array).unwrap();
    assert!(cases.len() > 2000);
    for c in cases {
        let (src, dst) = (s(c, "source_text"), s(c, "translated_text"));
        let ctx = format!("{src:?} / {dst:?}");
        assert_eq!(has_unrequested_markup(src, dst), c.get("markup").unwrap().as_bool().unwrap(), "markup {ctx}");
        assert_eq!(clean_translation_pair(src, dst), s(c, "clean"), "clean {ctx}");
        assert_eq!(has_source_translation_pair(src, dst), c.get("pair").unwrap().as_bool().unwrap(), "pair {ctx}");
        assert_eq!(
            looks_untranslated(src, dst, opt(c, "source"), opt(c, "target")),
            c.get("untranslated").unwrap().as_bool().unwrap(),
            "untranslated {ctx} {:?}",
            opt(c, "source")
        );
    }
}

#[test]
fn test_parser_matches_python() {
    let f = fixture();
    for c in f.get("parser").and_then(Value::as_array).unwrap() {
        let raw = s(c, "raw");
        let n = c.get("n").and_then(Value::as_i64).unwrap() as usize;
        let expected: Vec<(usize, String)> = c
            .get("out")
            .and_then(Value::as_object)
            .unwrap()
            .iter()
            .map(|(k, v)| (k.parse().unwrap(), v.as_str().unwrap().to_string()))
            .collect();
        let got: Vec<(usize, String)> = parse_numbered_translations(raw, n).into_iter().collect();
        let mut expected = expected;
        expected.sort();
        assert_eq!(got, expected, "{raw:?} n={n}");
    }
}

#[test]
#[serial]
fn test_url_rules_match_python() {
    unsafe { std::env::remove_var(se_core::i18n::ENV_VAR) };
    se_core::i18n::set_language(None);
    let f = fixture();
    for c in f.get("normalize").and_then(Value::as_array).unwrap() {
        let url = s(c, "url");
        match normalize_external_chat_url(url) {
            Ok(v) => assert_eq!(Some(v.as_str()), opt(c, "ok"), "{url:?}"),
            Err(e) => assert_eq!(Some(e.to_string().as_str()), opt(c, "err"), "{url:?}"),
        }
        assert_eq!(api_key_transport_allowed(url), c.get("allowed").unwrap().as_bool().unwrap(), "{url:?}");
        assert_eq!(se_translate::pyurl::url_host(url).as_deref(), opt(c, "host"), "{url:?}");
    }
    let mut wrong = Vec::new();
    for c in f.get("local").and_then(Value::as_array).unwrap() {
        let host = s(c, "host");
        // The fixture comes from CPython on Windows, whose inet_aton is inet_addr (platform-specific legacy forms).
        if !cfg!(windows) && matches!(host, "4294967295" | "0x" | "0x.1" | "0xffffffff") {
            continue;
        }
        if is_local_network_host(Some(host)) != c.get("local").unwrap().as_bool().unwrap() {
            wrong.push(host.to_string());
        }
    }
    assert!(wrong.is_empty(), "{wrong:?}");
}
